 "content": "from collections import Counter


def transform(grid):
    """Fill gaps between consecutive non-background markers in each row/column."""
    if not grid:
        return []
    out = [row[:] for row in grid]
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    height = len(grid)
    width = max(map(len, grid))

    for r, row in enumerate(grid):
        marks = [c for c, value in enumerate(row) if value != background]
        for left, right in zip(marks, marks[1:]):
            for c in range(left + 1, right):
                if row[c] == background:
                    out[r][c] = 3

    for c in range(width):
        marks = [r for r, row in enumerate(grid) if c < len(row) and row[c] != background]
        for top, bottom in zip(marks, marks[1:]):
            for r in range(top + 1, bottom):
                if c < len(grid[r]) and grid[r][c] == background:
                    out[r][c] = 3

    return out
